//! Actual public streamed mapping/recorder checks, no private authority factory.
#[path="../../../shared/test_scratch.rs"]mod scratch;
use dmbc::input_snapshot::{RecordingInputs,FileSystemInputs};
use dm_preprocess::{SourceProvider,SourceAcquisitionLease,source_arena_credit::SourceArenaWork};
use dm_tree::frontend::{self,SettingExpressionQueries,FrontendConfig,FrontendDirectivePlan};
use std::{path::{Path,PathBuf},io,sync::Arc,collections::BTreeMap};
struct Inputs(RecordingInputs<FileSystemInputs>);
impl SourceProvider for Inputs{
 fn original_batch_source(&self)->io::Result<Option<&(dyn SourceProvider+Sync)>>{Ok(Some(self))}
 fn initial_environment(&self)->dm_preprocess::InitialEnvironment{self.0.initial_environment()}
 fn read(&self,p:&Path)->Result<String,String>{SourceProvider::read(&self.0,p)}
 fn path_presence_admitted(&self,p:&Path,w:&dyn SourceArenaWork)->io::Result<bool>{self.0.path_presence_admitted(p,w)}
 fn original_raw_source_open_admitted(&self,p:&Path,n:usize,w:&dyn SourceArenaWork,open:&mut dyn FnMut()->io::Result<dm_preprocess::OriginalRawOpenDecision>,read:&mut dyn FnMut(usize)->io::Result<()>,decode:&mut dyn FnMut(dm_preprocess::OriginalRawAllocationPlan<'_>)->io::Result<()>,acquired:&mut dyn FnMut(&SourceAcquisitionLease)->io::Result<()>)->io::Result<dm_preprocess::OriginalRawReadOutcome>{self.0.original_raw_source_open_admitted(p,n,w,open,read,decode,acquired)}
 fn original_source_bytes<'a>(&'a self,l:&'a SourceAcquisitionLease)->io::Result<Option<&'a[u8]>>{self.0.original_source_bytes(l)}
}
fn inputs()->Inputs{Inputs(RecordingInputs::new(FileSystemInputs,0).with_initial_environment(dm_preprocess::InitialEnvironment::OriginalChecker0290))}
fn prepare(root:&Path,source:&Inputs,db:&Arc<dmbc::query_db::QueryDb>)->frontend::DiagnosticFrontend{let queries=Arc::clone(db)as Arc<dyn SettingExpressionQueries>;let executor=dm_exec::BuildExecutor::new(1).unwrap();let seed=dm_tree::checker_builtins::original_analysis_seed().unwrap();frontend::build_for_original_analysis_with_state_checked(&root.join("deepquarry.dme"),source,&BTreeMap::new(),FrontendConfig{workers:1,engine:Some(seed.frontend_seed()),observer:None},None,&executor,None,&queries).unwrap()}
#[test]fn actual_mapping_exact_receipts_reject_other_recorder_and_occurrence_without_prepared_promotion(){let root=scratch::dir("actual-mapped-exact-source-validation");std::fs::create_dir_all(root.join("code")).unwrap();std::fs::write(root.join("deepquarry.dme"),"#include \"code/a.dm\"\n").unwrap();std::fs::write(root.join("code/a.dm"),"/datum/probe\n    var/value=1\n").unwrap();let db=Arc::new(dmbc::query_db::QueryDb::default());let first=inputs();let front=prepare(&root,&first,&db);let view=front.source_view().unwrap();let FrontendDirectivePlan::OriginalDiagnostic(plan)=view.original_plan()else{panic!("actual raw product required")};let rows=plan.occurrences().iter().enumerate().filter(|(n,_)|view.mapping().source_acquisition(*n).is_some()).map(|(n,row)|(n,Arc::clone(&row.path))).collect::<Vec<_>>();assert!(rows.len()>=2,"actual root and included source must both be observed");for(index,path)in &rows{first.0.check_recorded_mapping_observation(view.mapping(),*index,path).unwrap();let lease=view.mapping().source_acquisition(*index).unwrap();assert!(SourceProvider::source_acquisition(&first.0,path,lease.source_text()).is_none(),"actual raw lease must not populate ordinary PreparedSource acquisition cache")}
 let second=inputs();let sibling=prepare(&root,&second,&db);let sibling_view=sibling.source_view().unwrap();for(index,path)in &rows{assert!(second.0.check_recorded_mapping_observation(view.mapping(),*index,path).is_err(),"equal file bytes and fully populated sibling facts cannot replace SAME recorder issuer");assert!(first.0.check_recorded_mapping_observation(sibling_view.mapping(),*index,path).is_err())}assert!(first.0.check_recorded_mapping_observation(view.mapping(),rows[1].0,&rows[0].1).is_err(),"a genuine but different occurrence cannot stand in for its root");assert!(first.0.check_recorded_mapping_observation(view.mapping(),usize::MAX,&rows[0].1).is_err());}
